/**
 * Request body used to create a reservation.
 *
 * @remarks
 * The identifier is not included because it is generated by the backend when the reservation is created.
 */
export interface CreateReservationRequest {
  sportsCenterId: number;
  activityType: string;
  participantName: string;
  participants: number;
  weatherTemperature: number;
  reservedAt: string;
}
